mapper.select:
SELECT id, user_id, name, color, display_order, is_default
FROM categories
WHERE name = #{name}
  AND user_id = #{userId}
LIMIT 1

mapper.update:
UPDATE categories
SET name       = #{name},
    color      = #{color},
    updated_at = NOW()
WHERE id = #{id}
  AND user_id = #{userId}

mapper.delete:
DELETE FROM categories
WHERE id = #{id}
  AND user_id = #{userId}
